use vstd::prelude::*;

verus! {
    /// Returns `true` iff it is possible to serve `n` regular guests
    /// (each needs one cookie from either pile) and
    /// `m` special guests (each needs one cookie from pile `a`
    /// and one from pile `b`), given piles of sizes `a` and `b`.
    ///
    /// Equivalently:
    ///   1) Each pile has at least `m` cookies (so special guests can be served).
    ///   2) Total cookies `a + b` is at least `n + 2*m` (so all guests can be served).
    fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> (result: bool)
        // We assume there is at least one guest in total,
        // though the formula works even when n + m = 0.
        requires
            n as u16 + m as u16 > 0,
        ensures
            result
            == (
                // piles individually must cover the special guests
                a >= m && b >= m
                &&
                // total cookies must cover all servings
                (a as u16 + b as u16) >= (n as u16 + 2 * (m as u16))
            ),
    {
        // Check each pile has enough for the special guests
        let per_pile_ok: bool = a >= m && b >= m;

        // Compute total available and required in u16 to avoid overflow
        let total_avail: u16 = a as u16 + b as u16;
        let total_req:   u16 = n as u16 + 2 * (m as u16);

        per_pile_ok && total_avail >= total_req
    }
}

fn main() {
    // Example uses (not verified by verus, just for demonstration)
    assert!(solve_cookie_distribution(3, 4, 2, 1)); // true
    assert!(!solve_cookie_distribution(1, 1, 1, 1)); // false: each pile ok, but total 2 < 1+2
    assert!(!solve_cookie_distribution(5, 0, 3, 1)); // false: b < m
}